function diaNoMes(ano, mesIndex, dia) {
  const base = new Date(Date.UTC(ano, mesIndex, 1));
  const ultimo = new Date(Date.UTC(base.getUTCFullYear(), base.getUTCMonth() + 1, 0)).getUTCDate();
  const dd = String(Math.min(Math.max(1, dia), ultimo)).padStart(2, "0");
  const mm = String(base.getUTCMonth() + 1).padStart(2, "0");
  return base.getUTCFullYear() + "-" + mm + "-" + dd;
}

// Datas em texto (2026-03-15) comparam certo com < e >, sem virar objeto.
function hojeNoBrasil() {
  return new Date(Date.now() - 3 * 60 * 60 * 1000).toISOString().slice(0, 10);
}

const achados = $input.all().filter((i) => i.json && i.json.id && !i.json.error);
const hoje = hojeNoBrasil();

const novasDespesas = [];
const ajustesNaRegra = [];

for (const item of achados) {
  const f = item.json.fields || {};
  if (!f.Ativo) continue;

  const diaDoMes = Math.min(31, Math.max(1, Number(f.Dia_Do_Mes) || 1));
  const semFim = Boolean(f.Sem_Fim);
  let vencimento = String(f.Proxima_Geracao || "").slice(0, 10);
  let restantes = semFim ? Infinity : Math.max(0, Number(f.Restantes) || 0);

  if (!vencimento) continue;

  // Gera tudo o que ficou para tras, nao so o mes atual: se o sistema passou
  // dois meses sem ser aberto, as duas contas aparecem. O limite de 24 e uma
  // trava contra data cadastrada errada la no passado.
  let geradas = 0;
  while (vencimento <= hoje && restantes > 0 && geradas < 24) {
    const campos = {
      Descricao: f.Descricao || "Conta fixa",
      Valor: f.Valor || 0,
      Vencimento: vencimento,
      Status: "Pendente",
      Categoria: f.Categoria || "Outros",
      Forma_Pagamento: f.Forma_Pagamento || null,
      Observacoes: f.Observacoes || "",
      Recorrente_Ref: [item.json.id],
    };
    if (Array.isArray(f.Fornecedor_Ref) && f.Fornecedor_Ref.length) {
      campos.Fornecedor_Ref = f.Fornecedor_Ref;
    }
    novasDespesas.push({ fields: campos });

    geradas += 1;
    if (!semFim) restantes -= 1;

    const [ano, mes] = vencimento.split("-").map(Number);
    vencimento = diaNoMes(ano, mes, diaDoMes);
  }

  if (!geradas) continue;

  // A regra so volta atualizada depois de gerar: se algo falhar no meio, a
  // data antiga continua la e a proxima tentativa refaz o que faltou.
  ajustesNaRegra.push({
    id: item.json.id,
    fields: {
      Proxima_Geracao: vencimento,
      Restantes: semFim ? 0 : restantes,
      Ativo: semFim ? true : restantes > 0,
    },
  });
}

if (!novasDespesas.length) {
  return [{ json: { nada: true, gerou: 0 } }];
}

// Primeiro as despesas, depois as regras: o no de HTTP segue a ordem dos
// itens, entao a regra so avanca depois da conta ter sido criada.
const chamadas = [];
for (let i = 0; i < novasDespesas.length; i += 10) {
  chamadas.push({
    metodo: "POST", url: "https://api.airtable.com/v0/appjAmWXV7Zr33UqE/tblNduEKl2jY280V0",
    corpo: { typecast: true, records: novasDespesas.slice(i, i + 10) },
  });
}
for (let i = 0; i < ajustesNaRegra.length; i += 10) {
  chamadas.push({
    metodo: "PATCH", url: "https://api.airtable.com/v0/appjAmWXV7Zr33UqE/tblb8QplhcGRP6SZ7",
    corpo: { typecast: true, records: ajustesNaRegra.slice(i, i + 10) },
  });
}

return chamadas.map((c) => ({ json: { ...c, nada: false, gerou: novasDespesas.length } }));

